//! `levels/ffa.lvl` (HALF = 112, the demo default) and `levels/ffa_xl.lvl` (HALF = 168), generated by
//! `scripts/gen_ffa_level.py`: free-for-all maps with open void edges. Pinned for spawn quality (>= 24 pads, no mutual
//! sight lines, on solid ground, far apart), pickup placement, void edges, and that the geometry fits the numeric
//! limits the rest of the engine assumes.

use shinobi_sim::level::{parse_level_file, LevelBox, LevelFile};
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::spawn::blocked;

const EYE: f32 = 0.6;

fn load(name: &str) -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels").join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("{name}: {e}"))
}

const MAPS: [(&str, f32); 2] = [("ffa.lvl", 112.0), ("ffa_xl.lvl", 168.0)];

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

fn top_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn d2(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn both_maps_load_with_24_plus_spawns_and_a_pickup_set() {
    for (name, _) in MAPS {
        let l = load(name);
        assert!(l.level.spawns.len() >= 24, "{name}: {} spawns", l.level.spawns.len());
        assert!((12..=40).contains(&l.pickups.len()), "{name}: {} pickups", l.pickups.len());
        assert!(l.pickups.iter().all(|p| p.respawn_secs >= 10.0));
        assert!(l.level.boxes.len() >= 200, "{name}: {} boxes", l.level.boxes.len());
    }
}

#[test]
fn no_spawn_has_a_sight_line_to_any_other_spawn() {
    for (name, _) in MAPS {
        let l = load(name);
        let w = world(&l);
        let s = &l.level.spawns;
        let mut seen = Vec::new();
        for (i, a) in s.iter().enumerate() {
            for (j, b) in s.iter().enumerate().skip(i + 1) {
                for hb in [0.1, 0.81, 0.81 + EYE] {
                    let from = [a[0], a[1] + EYE, a[2]];
                    let to = [b[0], b[1] - 0.81 + hb, b[2]];
                    if !blocked(&w, from, to) {
                        seen.push((i, j, hb));
                    }
                }
            }
        }
        assert!(seen.is_empty(), "{name}: spawn pairs with a sight line (i, j, target height): {seen:?}");
    }
}

#[test]
fn spawns_stand_on_solid_ground_clear_of_geometry_and_far_apart() {
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for (name, half) in MAPS {
        let l = load(name);
        for s in &l.level.spawns {
            for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
                for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                    let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                    assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "{name}: spawn {s:?}: capsule point {p:?} is inside geometry");
                }
            }
            let ground = l.level.boxes.iter().filter_map(|b| top_at(b, s[0], s[2])).filter(|h| (h - (s[1] - reach)).abs() < 0.1).count();
            assert!(ground > 0, "{name}: spawn {s:?} floats");
            assert!(s[0].abs() < half - 8.0 && s[2].abs() < half - 8.0, "{name}: spawn {s:?} is on the void edge");
        }
        let n = l.level.spawns.len();
        let mut nearest = Vec::new();
        for i in 0..n {
            let m = (0..n).filter(|j| *j != i).map(|j| d2(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min);
            nearest.push(m);
        }
        let min = nearest.iter().copied().fold(f32::MAX, f32::min);
        assert!(min >= 20.0, "{name}: two spawns only {min:.1} m apart");
    }
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    for (name, _) in MAPS {
        let l = load(name);
        for p in &l.pickups {
            assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "{name}: pickup {:?} is inside geometry", p.pos);
            let support = l.level.boxes.iter().filter_map(|b| top_at(b, p.pos[0], p.pos[2])).any(|h| (p.pos[1] - h - 1.0).abs() < 0.3);
            assert!(support, "{name}: pickup {:?} is not ~1 m above a surface", p.pos);
        }
    }
}

#[test]
fn the_floor_covers_the_map_and_the_void_edges_are_open() {
    for (name, half) in MAPS {
        let l = load(name);
        let any = |p: [f32; 3]| l.level.boxes.iter().any(|b| inside(b, p));
        let mut x = -half + 0.5;
        while x < half {
            let mut z = -half + 0.5;
            while z < half {
                assert!(any([x, -0.25, z]), "{name}: floor gap at ({x}, {z})");
                z += 4.0;
            }
            x += 4.0;
        }
        // beyond the floor there is nothing: falling off an edge reaches the kill plane
        for p in [[half + 3.0, 0.5, 0.0], [-half - 3.0, 0.5, 0.0], [0.0, 0.5, half + 3.0], [0.0, 0.5, -half - 3.0]] {
            assert!(!any(p), "{name}: something stands outside the void edge at {p:?}");
        }
        // every side has gaps in the lip (an open void edge you can walk off)
        for k in 0..4 {
            let open = (-(half as i32)..half as i32).step_by(2).filter(|i| {
                let t = *i as f32 + 0.5;
                let p = match k {
                    0 => [t, 0.5, -half + 0.25],
                    1 => [t, 0.5, half - 0.25],
                    2 => [-half + 0.25, 0.5, t],
                    _ => [half - 0.25, 0.5, t],
                };
                !any(p)
            }).count();
            assert!(open >= 8, "{name}: side {k} has only {open} open void cells");
        }
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    // replicated positions are quantised to 1/512 m in an i32 (plenty), and the extents must stay inside the ranges the
    // rest of the stack was sized for: report the numbers so a change that outgrows them fails here
    for (name, half) in MAPS {
        let l = load(name);
        let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
        let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
        assert!(far <= half + 1.0, "{name}: geometry reaches {far} m");
        assert!(top <= 60.0, "{name}: tallest geometry {top} m");
        let q = shinobi_proto::quant::q_pos3([2.0 * half, top, 2.0 * half]);
        let back = shinobi_proto::quant::dq_pos3(q);
        assert!((back[0] - 2.0 * half).abs() < 0.01 && (back[2] - 2.0 * half).abs() < 0.01, "{name}: q_pos3 loses precision at {half}");
    }
}
